export type ReviewPolicy = 'after_submission' | 'after_pass' | 'after_last_attempt' | 'never';
export type QuizSettings = {
  status: 'draft' | 'published';
  maxAttempts: number | null;
  timeLimitMinutes: number | null;
  passingPercent: number | null;
  reviewPolicy: ReviewPolicy;
  shuffleQuestions: boolean;
  shuffleOptions: boolean;
  availableFrom: Date | null;
  availableUntil: Date | null;
};
export type StoredQuestion = { id: string; question: string; options: string[]; correctAnswer: number; points: number; explanation: string };
export type Invalid = { ok: false; status: number; code: string; field: string; error: string };
export type AttemptResult = { earned: number; available: number; percent: number; passed: boolean | null; correctCount: number; answeredCount?: number; total: number };
export type AttemptView = {
  id: string;
  number: number;
  status: 'in_progress' | 'submitted' | 'expired' | 'cancelled';
  startedAt: string;
  deadlineAt: string | null;
  serverNow: string;
  submittedAt: string | null;
  questions: { id: string; question: string; options: string[]; points: number }[];
  answers: Record<string, number>;
  result?: AttemptResult;
  reviewAvailable?: boolean;
  review?: { id: string; correctAnswer: number; correct: boolean; explanation: string }[];
};
export const LEGACY_SETTINGS: QuizSettings;
export const MAX_ATTEMPTS_LIMIT: number;
export const MAX_QUESTIONS: number;
export const MAX_TIME_LIMIT_MINUTES: number;
export const REVIEW_POLICIES: readonly ReviewPolicy[];
export const FINISHED_STATUSES: readonly string[];
export const SUBMIT_GRACE_SECONDS: number;
export function attemptOverdue(attempt: any, now?: Date): boolean;
export function attemptCompletesLesson(attempt: any): boolean;
export function presentAttemptForStaff(attempt: any): Record<string, unknown>;
export function normalizeQuestions(input: unknown, options?: { random?: () => number }): { ok: true; questions: StoredQuestion[] } | Invalid;
export function normalizeSettings(input: unknown, current?: Partial<QuizSettings>): { ok: true; settings: QuizSettings } | Invalid;
export function quizSettings(quiz: any): QuizSettings;
export function quizAvailability(quiz: any, now?: Date): { ok: true; settings: QuizSettings } | { ok: false; status: number; code: string; error: string };
export function buildAttemptQuestions(quiz: any, options?: { random?: () => number }): any[];
export function attemptDeadline(startedAt: Date, settings: QuizSettings): Date | null;
export function scoreAttempt(questions: any[], answers: any, passingPercent: number | null): AttemptResult & { perQuestion: any[] };
export function reviewAllowed(attempt: any, attempts: any[], settings: QuizSettings): boolean;
export function presentAttempt(attempt: any, options?: { now?: Date; review?: boolean }): AttemptView;
export function presentQuizSummary(quiz: any): Record<string, unknown>;
export function presentQuizForStaff(quiz: any): { questions: StoredQuestion[]; settings: Record<string, unknown>; version: number };
